		public AssetTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Asset
		 * 
		 * @return Asset
		 */
		protected Asset generateNewEntity() {
			Asset entity = new Asset( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),  null,  null,  new HashSet<>(),  new HashSet<>(),  AssetStatus.values()[0] );
			
			return( entity );
		}

